param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$input=Join-Path $root 'input';$out=Join-Path $root 'outputs';$drafts=Join-Path $out 'reply_drafts';$attachments=Join-Path $out 'attachments';New-Item -ItemType Directory -Force -Path $drafts,$attachments | Out-Null
try{$rows=@();$counts=@{};$copied=0;foreach($file in Get-ChildItem (Join-Path $input 'emails') -Filter '*.eml'|Sort-Object Name){$raw=Get-Content -Raw $file.FullName;$parts=$raw -split "\r?\n\r?\n",2;$header=$parts[0];$body=if($parts.Count -gt 1){$parts[1]}else{''};$from=[regex]::Match($header,'(?m)^From:\s*(.*)$').Groups[1].Value.Trim();$subject=[regex]::Match($header,'(?m)^Subject:\s*(.*)$').Groups[1].Value.Trim();$attach=[regex]::Match($header,'(?m)^Attachment:\s*(.*)$').Groups[1].Value.Trim();$text=($subject+' '+$body).ToLowerInvariant();if($text.Contains('urgent')){$category='Urgent'}elseif($text.Contains('complaint')){$category='Complaint'}elseif($text.Contains('invoice')){$category='Invoice'}elseif($text.Contains('request')){$category='Request'}else{$category='General'};$counts[$category]=1+$(if($counts.ContainsKey($category)){$counts[$category]}else{0});$attachmentStatus='None';if($attach){$src=Join-Path (Join-Path $input 'attachment-fixtures') $attach;if(Test-Path $src){Copy-Item $src (Join-Path $attachments $attach) -Force;$copied++;$attachmentStatus='Copied'}else{$attachmentStatus='Missing fixture'}};$draft="To: $from`r`nSubject: Re: $subject`r`n`r`nDraft only - no message was sent.`r`n`r`nThank you for contacting the local automation desk. Your message was classified as $category. A team member can review it and respond through the approved channel.";$draftPath=Join-Path $drafts ($file.BaseName+'_reply_draft.txt');Set-Content $draftPath $draft -Encoding UTF8;$rows+=[pscustomobject]@{File=$file.Name;Sender=$from;Subject=$subject;Category=$category;Attachment=$attach;AttachmentStatus=$attachmentStatus;ReplyDraft=[IO.Path]::GetFileName($draftPath);Sent=$false}};$rows|Export-Csv (Join-Path $out 'classification_report.csv') -NoTypeInformation;$summary=[pscustomobject]@{TotalMessages=$rows.Count;CategoryCounts=$counts;AttachmentsCopied=$copied;ReplyDrafts=$rows.Count;MessagesSent=0;MessagesDeleted=0;ExternalConnections=0};$summary|ConvertTo-Json -Depth 5|Set-Content (Join-Path $out 'summary.json') -Encoding UTF8;if($rows.Count -ne 4 -or $summary.MessagesSent -ne 0){throw 'Email safety or count verification failed'};Write-Output "Classified $($rows.Count) local messages; copied $copied attachment(s); sent 0 messages."}catch{$_|Out-String|Set-Content (Join-Path $out 'error.log');throw}
